import{z as t,x as i,o as r,c as m,q as B,j as l,D as E,d as s,s as o,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"Garman–Klass 估计量","description":"","frontmatter":{"title":"Garman–Klass 估计量","date":"2026-09-27T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/garman-klass.md","filePath":"quant/garman-klass.md","lastUpdated":1791063341000}'),d={name:"quant/garman-klass.md"};function p(C,a,u,c,_,h){const n=i("Mermaid");return r(),m("div",null,[a[2]||(a[2]=B('<h1 id="garman–klass-估计量" tabindex="-1">Garman–Klass 估计量 <a class="header-anchor" href="#garman–klass-估计量" aria-label="Permalink to &quot;Garman–Klass 估计量&quot;">​</a></h1><div class="epigraph"><p>同一根 K 线里的高与低，携带的信息约为收盘到收盘的七倍——前提是价格连续、无漂移、开盘无跳空；破一条，效率就换方向。</p><footer>—— 据 Garman and Klass, Journal of Business, 1980</footer></div><p><a href="/quant/ornstein-uhlenbeck">上一课</a>把价差动力学写成 OU，方程里的 \\(\\sigma\\) 通常拿收盘对收盘去估——一天只攒一个样本点。K 线的开、高、低、收四价每天都在那里闲着。Garman–Klass 把四价拧成一个估计量，理想条件下效率约为 close-to-close 的 7.4 倍；前提破一条，偏差就从另一头进来。本课写公式、写效率从哪来、写每条假设被违背时偏差往哪边走，不重讲极值分布的推导。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>已实现波动的原料是样本量：close-to-close 每个交易日贡献一个 \\(r_t^2\\)，一百天才有一百个自由度，年化估计的噪声大得难堪。盘中高低价把日内整条路径压缩成两个极值，信息密度高得多。但 1980 年的推导假定：几何布朗运动、漂移为零、路径连续、开盘无跳空。真实股票隔夜必然跳、漂移常年非零、微观噪声让高低价虚胖。本课写 GK 本体与失效方向；pre-averaging 与核估计族不展开，隐含那一侧归 <a href="/quant/vol-surface">波动率曲面</a>。</p><p><span class="marginnote">术语翻译：估计量的「效率」是方差比的倒数——同一真值下估计量方差越小效率越高；效率 7.4 的意思是达到同样精度，close-to-close 要用约 7.4 倍的样本天数。OHLC 四价即开盘、最高、最低、收盘，一根 K 线的全部廉价信息。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记 \\(o_i=\\ln(O_i/C_{i-1})\\)、\\(u_i=\\ln(H_i/L_i)\\)、\\(c_i=\\ln(C_i/O_i)\\)，估计量为</p> \\[\\hat\\sigma_{\\mathrm{GK}}^2=\\frac{1}{n}\\sum_{i=1}^n\\left[\\,o_i^2+0.5\\,u_i^2-(2\\ln 2-1)\\,c_i^2\\,\\right] \\]<p>很多实现把 \\(o_i^2\\) 一项静默丢掉——那等于宣布隔夜方差不存在。<span class="marginnote">数字实例：一根日内高低比 2% 的 bar，\\(u=\\ln 1.02\\approx0.0198\\)；若开收几乎持平（\\(c\\approx0\\)），该 bar 贡献 \\(0.5u^2\\approx1.96\\times10^{-4}\\)，对应日波动约 1.4%，年化约 \\(1.4\\%\\times\\sqrt{252}\\approx22\\%\\)——一根 bar 就把量级立起来。</span></p>',10)),(r(),l(A,null,{default:E(()=>[o(n,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20DATA%5B%22%E5%8F%96%E6%97%A5%E9%A2%91%20OHLC%20%E5%BA%8F%E5%88%97%22%5D%20--%3E%20LOG%5B%22%E5%9B%9B%E4%BB%B7%E5%8F%96%E5%AF%B9%E6%95%B0%E5%81%9A%E5%B7%AE%22%5D%0A%20%20LOG%20--%3E%20TERM%5B%22%E9%80%90%20bar%20%E7%AE%97%20o2%20%E5%8A%A0%200.5u2%20%E5%87%8F%E4%BF%AE%E6%AD%A3%E9%A1%B9%22%5D%0A%20%20TERM%20--%3E%20AVG%5B%22%E5%8F%96%20n%20%E6%97%A5%E5%B9%B3%E5%9D%87%E5%BE%97%E6%97%A5%E6%96%B9%E5%B7%AE%22%5D%0A%20%20AVG%20--%3E%20ANN%5B%22%E4%B9%98%20252%20%E5%BC%80%E6%A0%B9%E5%8F%B7%E5%B9%B4%E5%8C%96%22%5D%0A%20%20ANN%20--%3E%20CHK%7B%22%E5%8D%95%20bar%20%E9%A1%B9%E5%87%BA%E7%8E%B0%E8%B4%9F%E5%80%BC%E5%90%97%22%7D%0A%20%20CHK%20--%3E%7C%22%E5%81%B6%E5%B0%94%22%7C%20AVG%0A%20%20CHK%20--%3E%7C%22%E9%A2%91%E7%B9%81%22%7C%20WARN%5B%22%E5%99%AA%E5%A3%B0%E8%BF%87%E9%87%8D%EF%BC%9A%E6%8D%A2%E4%BD%8E%E9%A2%91%E6%88%96%E6%8D%A2%E4%BC%B0%E8%AE%A1%E9%87%8F%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[s("效率来自极值统计：固定方差的 GBM 在单位时间内，对数极差的期望平方正比于 \\(\\sigma^2\\)，比例系数是常数——这是 Parkinson 一族的根本。GK 用高低差捕捉「路径一天走了多远」，再用 \\((2\\ln2-1)\\approx0.386\\) 的负项扣掉开收段，避免与 \\(o^2\\)、\\(c^2\\) 重复计数，所以效率高于纯极差的 Parkinson（约 5 倍）。极值对路径形状不挑食，但正因如此，任何把极值弄虚的东西都会直接进估计量。"),e("span",{class:"marginnote"},"常见误区：把效率倍数当万灵药，任何数据上来就 GK。错在假设核对被跳过——隔夜方差占比可观的品种，丢掉 \\(o^2\\) 项的 GK 系统性低估年化波动好几个百分点，此时「高效率」估的是一个错误的量。")],-1)),(r(),l(A,null,{default:E(()=>[o(n,{id:"mermaid-33",class:"mermaid",graph:"flowchart%20TD%0A%20%20REAL%5B%22%E7%9C%9F%E5%AE%9E%E5%B8%82%E5%9C%BA%22%5D%20--%3E%20Q1%7B%22%E9%9A%94%E5%A4%9C%E6%9C%89%E8%B7%B3%E7%A9%BA%E5%90%97%22%7D%0A%20%20Q1%20--%3E%7C%22%E6%9C%89%E4%B8%94%E5%85%AC%E5%BC%8F%E4%B8%A2%E4%BA%86%20o%20%E9%A1%B9%22%7C%20UNDER%5B%22%E7%B3%BB%E7%BB%9F%E6%80%A7%E4%BD%8E%E4%BC%B0%EF%BC%9A%E9%9A%94%E5%A4%9C%E6%96%B9%E5%B7%AE%E6%B2%A1%E8%BF%9B%E8%B4%A6%22%5D%0A%20%20REAL%20--%3E%20Q2%7B%22%E6%BC%82%E7%A7%BB%E9%9D%9E%E9%9B%B6%E5%90%97%22%7D%0A%20%20Q2%20--%3E%7C%22%E6%98%AF%22%7C%20POLL%5B%22%E4%BA%A4%E5%8F%89%E9%A1%B9%E8%A2%AB%E6%B1%A1%E6%9F%93%EF%BC%9A%E5%81%8F%E5%B7%AE%E9%9A%8F%E5%91%A8%E6%9C%9F%E6%94%BE%E5%A4%A7%22%5D%0A%20%20REAL%20--%3E%20Q3%7B%22%E4%B9%B0%E5%8D%96%E6%A1%A3%E6%9D%A5%E5%9B%9E%E6%89%93%E5%90%97%22%7D%0A%20%20Q3%20--%3E%7C%22%E6%98%AF%22%7C%20FAT%5B%22%E9%AB%98%E4%BD%8E%E4%BB%B7%E8%99%9A%E8%83%96%EF%BC%9A%E9%AB%98%E4%BC%B0%E6%97%A5%E5%86%85%E6%96%B9%E5%B7%AE%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=B('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>假设清单变对照表：涨跌停封板与集合竞价 bar 会把高低差压平，低估随之而来；噪声重时单 bar 项可为负，靠滚动平均兜住、频繁为负就该换估计量。OU 的带宽用哪个 \\(\\sigma\\) 估，直接影响上一课的入场线——测量口径是动力学的上游。<span class="marginnote">直觉类比：把估计量当温度计——close-to-close 一天读一次刻度，GK 一天读日内两个极值加首尾；读数多的温度计更稳，但若水银柱被人捏着（封板、停牌），读得越多错得越一致。</span>跳空与漂移两根刺本课只指出没拔掉，下一课的 Yang–Zhang 专门处理。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>GK 合并 OHLC 四价，理想条件下效率约为 close-to-close 的 7.4 倍。</li><li>效率来自极值信息，\\((2\\ln2-1)\\) 修正项负责去重。</li><li>三条假设逐条核：丢 \\(o^2\\) 低估隔夜、漂移污染交叉项、噪声吹胖极值。</li><li>封板与停牌 bar 的极值不可信，测量口径是下游模型的上游。</li><li>出处：Garman and Klass, <em>Journal of Business</em>, 1980；Parkinson, <em>Journal of Business</em>, 1980；Rogers and Satchell, 1991 对照。</li></ul>',4))])}const F=t(d,[["render",p]]);export{f as __pageData,F as default};
